const TOTAL_PAGES = 111;
const DAYS = 6;
const PAGES_PER_DAY = 19;

const CONFIG = {
  accountName: '饼干哥哥AGI',
  apiKey: 'JZLdc9670be1403c05c',
  baseUrl: 'https://www.dajiala.com/fbmain/monitor/v3/post_history',
  pagesPerDay: PAGES_PER_DAY,
  delayMs: 3000,
  contentDelayMs: 5000
};

const FEISHU_CONFIG = {
  appId: 'cli_a907365bcefbdbd2',
  appSecret: 'UOnIdOt4xWAgLrzVJUmrQbAOu8Icetjv'
};

return [{
  json: {
    config: CONFIG,
    feishu: FEISHU_CONFIG,
    currentPage: 1,
    startPage: 1,
    endPage: PAGES_PER_DAY,
    totalPages: TOTAL_PAGES,
    allArticles: [],
    totalCost: 0,
    dayInfo: {
      currentDay: 1,
      totalDays: DAYS
    },
    phase: 'fetch_list'
  }
}];

const response = $input.first().json;
const endPage = $input.first().json.endPage;

if (response.code !== 0) {
  if (response.code === 110 || response.code === 115) {
    return [{json: {...$input.first().json, hasMore: false}}];
  }
  throw new Error(`API错误: ${response.msg}`);
}

const articles = response.data || [];
const currentPage = $input.first().json.currentPage;
const allArticles = $input.first().json.allArticles || [];

const existingIds = new Set(allArticles.map(a => a.appmsgid));
const newArticles = articles.filter(a => !existingIds.has(a.appmsgid)).map(a => ({
  ...a,
  content: null,
  contentFetched: false
}));
allArticles.push(...newArticles);

const hasMore = currentPage < endPage;
console.log(`第 ${currentPage} 页: ${newArticles.length} 篇新文章`);

return [{
  json: {
    ...$input.first().json,
    articles: newArticles,
    allArticles,
    hasMore,
    nextPage: currentPage + 1,
    remainMoney: response.remain_money,
    totalCost: ($input.first().json.totalCost || 0) + (response.cost_money || 0)
  }
}];

// 开始抓取文章内容阶段
const data = $input.first().json;
const articlesNeedContent = data.allArticles.filter(a => !a.contentFetched);

console.log(`共 ${data.allArticles.length} 篇文章，需要抓取内容: ${articlesNeedContent.length} 篇`);

if (articlesNeedContent.length === 0) {
  return [{
    json: {
      ...data,
      phase: 'create_document',
      currentArticleIndex: 0
    }
  }];
}

return [{
  json: {
    ...data,
    phase: 'fetch_content',
    articlesNeedContent,
    currentArticleIndex: 0,
    currentArticle: articlesNeedContent[0]
  }
}];

// 解析微信公众号文章内容
const html = $input.first().json.data || $input.first().json;
const data = $input.first().json;
const currentArticle = data.currentArticle;

try {
  // 使用正则表达式提取内容
  let content = '';

  // 尝试提取rich_media_content中的内容
  const contentMatch = html.match(/<div class="rich_media_content[^"]*"[^>]*>([\s\S]*?)<\/div>\s*<\/div>\s*<script/i);
  if (contentMatch) {
    content = contentMatch[1];
  } else {
    // 备用方案：提取id为js_content的元素
    const jsContentMatch = html.match(/id="js_content"[^>]*>([\s\S]*?)<\/div>/i);
    if (jsContentMatch) {
      content = jsContentMatch[1];
    }
  }

  // 清理HTML标签
  content = content
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&quot;/g, '

const data = $input.first().json;
const nextIndex = data.currentArticleIndex + 1;

return [{
  json: {
    ...data,
    currentArticleIndex: nextIndex,
    currentArticle: data.articlesNeedContent[nextIndex]
  }
}];

// 所有内容抓取完成，准备创建飞书文档
const data = $input.first().json;

console.log(`所有文章内容抓取完成，共 ${data.allArticles.length} 篇`);

return [{
  json: {
    ...data,
    phase: 'create_document'
  }
}];

// 生成飞书文档块
const data = $input.first().json;
const articles = data.allArticles;

const blocks = [];

// 文档标题
blocks.push({
  block_type: 'page',
  page: {
    elements: [{
      type: 'textRun',
      textRun: {
        content: `📰 饼干哥哥AGI - 第${data.dayInfo.currentDay}天文章汇总`
      }
    }]
  }
});

// 统计信息
blocks.push({
  block_type: 'paragraph',
  paragraph: {
    elements: [{
      type: 'textRun',
      textRun: {
        content: `抓取时间: ${new Date().toLocaleString()} | 文章数: ${articles.length}篇 | 费用: ${data.totalCost.toFixed(2)}元`
      }
    }]
  }
});

// 分隔线
blocks.push({block_type: 'divider', divider: {}});

// 每篇文章
articles.forEach((article, idx) => {
  // 文章标题
  blocks.push({
    block_type: 'heading2',
    heading2: {
      elements: [{
        type: 'textRun',
        textRun: {
          content: `${idx + 1}. ${article.title}`
        }
      }]
    }
  });

  // 文章元信息
  blocks.push({
    block_type: 'paragraph',
    paragraph: {
      elements: [{
        type: 'textRun',
        textRun: {
          content: `🕐 ${article.post_time_str} | ${article.original === 1 ? '原创' : '转载'}`,
          text_style: {
            italic: true,
            text_color: 5
          }
        }
      }]
    }
  });

  // 原文链接
  blocks.push({
    block_type: 'paragraph',
    paragraph: {
      elements: [{
        type: 'textRun',
        textRun: {
          content: `🔗 阅读原文: ${article.url}`,
          text_style: {
            text_color: 1,
            bold: true
          }
        }
      }]
    }
  });

  // 文章正文内容
  if (article.content && article.content !== '内容抓取失败') {
    // 内容分段（每段不超过500字符）
    const content = article.content;
    const paragraphs = [];
    for (let i = 0; i < content.length; i += 500) {
      paragraphs.push(content.substring(i, i + 500));
    }

    paragraphs.forEach(para => {
      if (para.trim()) {
        blocks.push({
          block_type: 'paragraph',
          paragraph: {
            elements: [{
              type: 'textRun',
              textRun: {
                content: para
              }
            }]
          }
        });
      }
    });
  } else {
    // 摘要作为备选
  blocks.push({
    block_type: 'paragraph',
    paragraph: {
      elements: [{
        type: 'textRun',
        textRun: {
          content: `摘要: ${article.digest || '暂无摘要'}`,
              text_style: {
                text_color: 5
              }
        }
      }]
    }
  });
  }

  // 文章分隔
  blocks.push({block_type: 'divider', divider: {}});
});

return [{
  json: {
    ...data,
    tenant_access_token: $input.first().json.tenant_access_token,
    blocks: blocks.slice(0, 500), // 飞书限制单次最多500块
    totalBlocks: blocks.length
  }
}];

const data = $input.first().json;

return [{
  json: {
    status: 'success',
    message: `✅ 第 ${data.dayInfo.currentDay} 天完成！\n📄 文档: ${data.data.document.title}\n📊 文章: ${data.allArticles.length} 篇\n💰 费用: ${data.totalCost.toFixed(2)} 元\n📄 文档ID: ${data.data.document.document_id}`,
    documentUrl: `https://www.feishu.cn/docx/${data.data.document.document_id}`,
    documentId: data.data.document.document_id
  }
}];
